import unittest
from candidate import mean_absolute_deviation

class TestMeanAbsoluteDeviation(unittest.TestCase):
    def test_normal_case(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0, 2.0, 3.0, 4.0]), 1.0)

    def test_small_dataset(self):
        self.assertAlmostEqual(mean_absolute_deviation([5.0]), 0.0)

    def test_even_spaced_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0, 3.0, 5.0, 7.0]), 2.0)

    def test_negative_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([-1.0, -2.0, -3.0, -4.0]), 1.0)

    def test_mixed_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([-2.0, 0.0, 2.0, 4.0]), 2.0)

    def test_floats(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.5, 2.5, 3.5]), 0.5)

    def test_boundary_case_minus_max(self):
        self.assertAlmostEqual(mean_absolute_deviation([-10.0, 10.0]), 10.0)

    def test_boundary_case_single_element(self):
        self.assertAlmostEqual(mean_absolute_deviation([0.0]), 0.0)

    def test_empty_list(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation("not a list")

    def test_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([1, 2, "three"])

    def test_very_small_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([0.0001, 0.0002, 0.0003]), 0.00005)

    def test_very_large_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([1e10, 2e10, 3e10]), 1e10 / 3)

    def test_duplicate_values(self):
        self.assertAlmostEqual(mean_absolute_deviation([2.0, 2.0, 2.0]), 0.0)

    def test_negative_mean(self):
        self.assertAlmostEqual(mean_absolute_deviation([-5.0, -3.0, -1.0]), 2.0)

    def test_duplicates_with_mean(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0, 1.0, 1.0, 3.0]), 1.0)
